    stack = []
    for t in tokens:
        # Try to parse as int
        try:
            val = int(t)
            stack.append(val)
        except ValueError:
            # Operator
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                stack.append(a + b)
            elif t == '-':
                stack.append(a - b)
            elif t == '*':
                stack.append(a * b)
            elif t == '/':
                # Truncate toward zero
                stack.append(int(a / b))
            else:
                raise ValueError('Invalid token')
    return stack[0] if stack else 0

