def solve(nested):
    """Flatten an arbitrarily nested list into a single flat list.

    Iterative stack-based traversal; descends into any iterable that is not a
    str/bytes (so tuples and other sequences also flatten).
    """
    result = []
    stack = [nested]
    while stack:
        current = stack.pop()
        if isinstance(current, (str, bytes)):
            result.append(current)
        elif isinstance(current, (list, tuple)):
            stack.extend(reversed(current))
        else:
            result.append(current)
    return result

