def solve(weights, values, capacity):
    n = len(weights)
    dp = [0]*(capacity+1)
    for i in range(n):
        w = weights[i]
        v = values[i]
        # iterate backward to avoid reuse
        for c in range(capacity, w-1, -1):
            new_val = dp[c-w] + v
            if new_val > dp[c]:
                dp[c] = new_val
    return dp[capacity]

