def solve(s):
    """Return True if *s* is a valid IPv4 address.
    The address must consist of exactly four decimal numbers separated by periods.
    Each number must be in the range 0-255, contain only digits, and must not have leading
    zeros unless the number itself is zero.
    """
    if not isinstance(s, str):
        return False
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        # each part must be non‑empty and all digits
        if not part or not part.isdigit():
            return False
        # no leading zeros, unless the part is exactly '0'
        if len(part) > 1 and part[0] == '0':
            return False
        # numeric range check
        val = int(part)
        if val < 0 or val > 255:
            return False
    return True

