    Islands are groups of horizontally or vertically adjacent 1s. The grid may be empty
    or have rows of varying lengths; cells outside the provided row length are ignored.
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = set()
    def get_neighbors(r, c):
        for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < len(grid[nr]):
                yield nr, nc
    def bfs(r, c):
        stack = [(r, c)]
        while stack:
            cr, cc = stack.pop()
            if (cr, cc) in visited:
                continue
            visited.add((cr, cc))
            for nr, nc in get_neighbors(cr, cc):
                if grid[nr][nc] == 1 and (nr, nc) not in visited:
                    stack.append((nr, nc))
    count = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if grid[i][j] == 1 and (i, j) not in visited:
                bfs(i, j)
