def solve(a,b):
    # Use O(min(len(a), len(b))) space DP for Levenshtein distance.
    # Ensure a is the shorter string to minimise space.
    if len(a) > len(b):
        a,b = b,a
    n,m = len(a), len(b)
    # previous row
    prev = list(range(n+1))
    for j in range(1, m+1):
        cur = [j] + [0]*n
        bj = b[j-1]
        for i in range(1, n+1):
            if a[i-1] == bj:
                cur[i] = prev[i-1]
            else:
                cur[i] = 1 + min(prev[i], cur[i-1], prev[i-1])
        prev = cur
    return prev[n]

