def solve(matrix):
    """Compute the determinant of an integer matrix using Bareiss algorithm.
    Returns an integer. The determinant of an empty matrix (0x0) is defined as 1.
    """
    # Empty matrix case
    if not matrix:
        return 1
    n = len(matrix)
    # Verify square
    for row in matrix:
        if len(row) != n:
            raise ValueError("Matrix must be square")
    # Make a deep copy to avoid mutating input
    A = [list(row) for row in matrix]
    det_sign = 1
    # Bareiss algorithm
    for k in range(n-1):
        # Pivot selection: if A[k][k] == 0, find a row to swap
        if A[k][k] == 0:
            swap_row = None
            for i in range(k+1, n):
                if A[i][k] != 0:
                    swap_row = i
                    break
            if swap_row is None:
                return 0
            # swap rows k and swap_row
            A[k], A[swap_row] = A[swap_row], A[k]
            det_sign = -det_sign
        pivot = A[k][k]
        for i in range(k+1, n):
            for j in range(k+1, n):
                # Bareiss update formula
                A[i][j] = (A[i][j]*pivot - A[i][k]*A[k][j])
                if k > 0:
                    A[i][j] //= A[k-1][k-1]
            A[i][k] = 0
    det = det_sign * A[n-1][n-1]
    return det

def solve(s):
    if not s:
        return ''
    n = len(s)
    start = 0
    max_len = 1
    def expand(l, r):
        while l >= 0 and r < n and s[l] == s[r]:
            l -= 1
            r += 1
        return l+1, r-1
    for i in range(n):
        # odd length
        l1, r1 = expand(i, i)
        if r1 - l1 + 1 > max_len:
            start = l1
            max_len = r1 - l1 + 1
        # even length
        l2, r2 = expand(i, i+1)
        if r2 - l2 + 1 > max_len:
            start = l2
            max_len = r2 - l2 + 1
    return s[start:start+max_len]

