def solve(s) -> bool:
    """Balanced brackets check for batch 2.
    Returns True if every round, square and curly bracket in *s* is properly nested.
    Non‑string inputs are considered invalid and return False.
    """
    if not isinstance(s, str):
        return False
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    opening = set(pairs.values())
    closing = set(pairs.keys())
    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in closing:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return not stack

